 let center={x:4250,y:4250,mass:100},own=snap?.players.find(p=>p.id===S.pid),cells=own?.cells||[];if(cells.length){let m=0,x=0,y=0;for(const c of cells){m+=c.mass;x+=c.x*c.mass;y+=c.y*c.mass}center={x:x/m,y:y/m,mass:m}}else if(snap?.players.length){const pp=snap.players.find(p=>p.id===snap.following?.id)||snap.players.find(p=>!p.boss)||snap.players[0];if(pp.cells[0])center={x:pp.cells[0].x,y:pp.cells[0].y,mass:pp.cells.reduce((s,c)=>s+c.mass,0)}}
