function updateHud(){const s=S.snapshot;if(!s)return;$('run-summary').hidden=!S.playing&&!S.lastRun;$('room-title').textContent=`${s.room} [${clock(s.timeLeft)}]`;$('room-subtitle').textContent=({nogold:'[Goldsuz Oda]',boss:'[Boss Fight]',special:'[Bonus Gold Odası]',area:'[Daralan Alan]',team:'[Takım Oyunu]'})[s.mode]||'';$('announcement').textContent=S.spectating?'İZLE: '+(s.following?.name||'Oyuncu bekleniyor')+' · 1 / Q / 2':S.replay?'TEKRAR İZLİYORSUN':!S.online?'ANTRENMAN · '+s.bots+' BOT':'';$('prize-hud').textContent='Ödül '+fmt(s.prize??50000);const self=s.self;$('score').textContent='Skor: '+fmt(self?.score||0);$('max-score').textContent='Maks.: '+fmt(self?.max||0);$('pieces').textContent=`Parçalar: ${self?.cells||0}/25`;$('gold-hud').textContent=(s.mode==='special'?'Bonus ':'Gold ')+fmt(s.mode==='special'?self?.bonus:self?.gold);$('leaders').innerHTML=s.ranking.map((p,i)=>`<li>${S.spectating?`<button class="ghost" data-spectate="${esc(p.id)}">${i+1}. ${esc(p.name)}</button>`:`${i+1}. ${esc(p.name)}`}${p.bot?' <small>BOT</small>':''}</li>`).join('');$('stats').hidden=!S.settings.info;$('stats').innerHTML=`Ping: ${S.online?(S.ping==null?'ölçülüyor':S.ping+' ms'):'— (yerel)'}<br>FPS: ${S.fps}<br>Oyuncu: ${s.humans} · Bot: ${s.bots}<br>Diken: ${s.viruses}<br>Oda: ${s.room}`;$('chat').style.visibility=S.settings.chat?'visible':'hidden';$('boss-bar').hidden=s.bossHealth==null;$('boss-health').value=s.bossHealth||0;const pp=s.players.find(p=>p.id===S.pid)||s.players[0],c=pp?.cells[0];mini.clearRect(0,0,120,120);mini.fillStyle='#ffffff0c';mini.fillRect(0,0,120,120);if(c){mini.fillStyle='#d4e1ed';mini.fillRect(c.x/s.size*120-2,c.y/s.size*120-2,4,4);$('sector').textContent=`${Math.ceil(c.x/s.size*32)}, ${Math.ceil(c.y/s.size*32)}`}}
function closeModal(){$('modal').hidden=true;S.page='';modalEpoch++;document.body.style.overflow='';if(S.replay){S.replay=null;S.playing=false;displayMenu(true)}}
